"""Triton implementation of torch.linalg.tensorinv.

tensorinv(A, ind) with n = prod(A.shape[:ind]) == prod(A.shape[ind:]) is just a
dense inverse of the n x n matrix M = A.reshape(n, n); the output has shape
A.shape[ind:] + A.shape[:ind] and its row-major flat buffer equals inv(M)'s.

n <= 128 uses one CTA that keeps both the matrix tile and the identity/RHS tile
in registers and runs a partial-pivoted Gauss-Jordan elimination (fast path).
Larger n uses a multi-launch Gauss-Jordan over global-memory workspaces with
one launch per elimination step, which is deterministic (no intra-launch
cross-phase synchronization is required).

Two refinement steps use compensated FP32 residuals to reduce elimination
roundoff on general matrices. Outputs retain the input dtype; this path does
not require FP64 support from the device.
"""

import torch
import triton
import triton.language as tl

_TILE_MAX = 128


def _check_inv_input(A, ind):
    if ind <= 0:
        raise RuntimeError(
            "linalg.tensorinv: Expected a strictly positive integer for "
            f"'ind', but got {ind}"
        )
    if A.dim() < 2:
        raise RuntimeError(
            f"linalg.tensorinv: Expected input to be at least 2D, got {A.dim()}D"
        )
    if ind > A.dim():
        raise RuntimeError(
            "linalg.tensorinv: Expected 0 <= ind <= input.dim(), "
            f"got ind={ind} for input.dim()={A.dim()}"
        )
    m = 1
    for i in range(ind):
        m *= A.shape[i]
    n = 1
    for i in range(ind, A.dim()):
        n *= A.shape[i]
    if m != n:
        raise RuntimeError(
            "linalg.tensorinv: Expected self to satisfy the requirement "
            "prod(self.shape[ind:]) == prod(self.shape[:ind]), "
            f"but got {n} != {m}"
        )


@triton.jit
def _tensorinv_tile_kernel(A, B, N, BLOCK: tl.constexpr, MASKED: tl.constexpr):
    """Partial-pivoted Gauss-Jordan, whole N x N tile resident in registers.

    MASKED is False exactly when N == BLOCK: the tile then covers the matrix
    exactly, so the kernel drops the predicate construction and uses
    unpredicated loads/stores.  This is bitwise neutral (verified on the target
    against the masked variant) and only removes prologue instructions.
    """
    rows = tl.arange(0, BLOCK)
    cols = tl.arange(0, BLOCK)
    offs = rows[:, None] * N + cols[None, :]

    if MASKED:
        mask = (rows[:, None] < N) & (cols[None, :] < N)
        a = tl.load(A + offs, mask=mask, other=0.0).to(tl.float32)
        b = tl.where((rows[:, None] == cols[None, :]) & mask, 1.0, 0.0)
    else:
        a = tl.load(A + offs).to(tl.float32)
        b = tl.where(rows[:, None] == cols[None, :], 1.0, 0.0)
    # Per-row scale of the unnormalised elimination (applied once at the end).
    # Only rows >= k are ever swapped, and those still hold scale 1.0 at step k,
    # so the row permutation needs no scale bookkeeping.
    scale = tl.full((BLOCK,), 1.0, tl.float32)

    for k in range(0, N):
        # Column k of the working matrix, extracted once: an axis=1 masked sum
        # lowers to a cross-lane butterfly here, so re-deriving it after the
        # (rare) row swap is folded into cheap axis=0 bookkeeping below.
        colk = tl.sum(tl.where(cols[None, :] == k, a, 0.0), axis=1)
        abs_col = tl.where((rows < k) | (rows >= N), -1.0, tl.abs(colk))
        # max + argmax in one reduction (ties pick the lowest row, matching the
        # previous max/min pair) instead of two dependent 1D reductions.
        pval, prow = tl.max(abs_col, axis=0, return_indices=True)
        piv = tl.sum(tl.where(rows == prow, colk, 0.0), axis=0)

        if prow != k:
            ck = tl.sum(tl.where(rows == k, colk, 0.0), axis=0)
            rk_a = tl.sum(tl.where(rows[:, None] == k, a, 0.0), axis=0)
            rp_a = tl.sum(tl.where(rows[:, None] == prow, a, 0.0), axis=0)
            rk_b = tl.sum(tl.where(rows[:, None] == k, b, 0.0), axis=0)
            rp_b = tl.sum(tl.where(rows[:, None] == prow, b, 0.0), axis=0)
            is_k = rows[:, None] == k
            is_p = rows[:, None] == prow
            a = tl.where(is_k, rp_a[None, :], tl.where(is_p, rk_a[None, :], a))
            b = tl.where(is_k, rp_b[None, :], tl.where(is_p, rk_b[None, :], b))
            # rows k and prow exchanged, so the column entries follow
            colk = tl.where(rows == k, piv, tl.where(rows == prow, ck, colk))

        # Eliminate with the unnormalised pivot row, folding 1/piv into the
        # factors; row k keeps its scale and is divided once after the loop.
        rk_a = tl.sum(tl.where(rows[:, None] == k, a, 0.0), axis=0)
        rk_b = tl.sum(tl.where(rows[:, None] == k, b, 0.0), axis=0)
        factor = tl.where(rows != k, colk * (1.0 / piv), 0.0)
        a = a - factor[:, None] * rk_a[None, :]
        b = b - factor[:, None] * rk_b[None, :]
        scale = tl.where(rows == k, piv, scale)

    if MASKED:
        tl.store(B + offs, b / scale[:, None], mask=mask)
    else:
        tl.store(B + offs, b / scale[:, None])


@triton.jit
def _tensorinv_init_kernel(A, W, R, N, BLOCK: tl.constexpr):
    """W = float32(A); R = identity, both stored row-major in global memory."""
    rows = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    cols = tl.program_id(1) * BLOCK + tl.arange(0, BLOCK)
    m = (rows[:, None] < N) & (cols[None, :] < N)
    o = rows[:, None] * N + cols[None, :]
    v = tl.load(A + o, mask=m, other=0.0).to(tl.float32)
    tl.store(W + o, v, mask=m)
    ident = (rows[:, None] == cols[None, :]) & m
    tl.store(R + o, tl.where(ident, 1.0, 0.0), mask=m)


@triton.jit
def _tensorinv_pivot_kernel(W, R, N, K, BS: tl.constexpr):
    """One CTA, one warp: swap row K with the pivot row and normalise row K.

    Every column strip is handled by the same thread across both passes, and
    each pass has no read-after-write dependency, so no intra-kernel barrier is
    needed.
    """
    best = tl.full((), -1.0, tl.float32)
    brow = tl.full((), 0, tl.int32)
    for i0 in range(K, N, BS):
        rows = i0 + tl.arange(0, BS)
        v = tl.load(W + rows * N + K, mask=rows < N, other=0.0)
        av = tl.where(rows < N, tl.abs(v), -1.0)
        mx = tl.max(av, axis=0)
        rw = tl.min(tl.where(av == mx, rows, N), axis=0)
        upd = mx > best
        best = tl.where(upd, mx, best)
        brow = tl.where(upd, rw, brow)

    piv = tl.load(W + brow * N + K)
    if brow == K:
        # no swap: normalise row K in place
        for j0 in range(0, N, BS):
            cols = j0 + tl.arange(0, BS)
            cm = cols < N
            ok = W + K * N + cols
            v = tl.load(ok, mask=cm, other=0.0) / piv
            tl.store(ok, v, mask=cm)
            rk = R + K * N + cols
            v = tl.load(rk, mask=cm, other=0.0) / piv
            tl.store(rk, v, mask=cm)
    else:
        for j0 in range(0, N, BS):
            cols = j0 + tl.arange(0, BS)
            cm = cols < N
            ok = W + K * N + cols
            op = W + brow * N + cols
            vk = tl.load(ok, mask=cm, other=0.0)
            vp = tl.load(op, mask=cm, other=0.0)
            tl.store(ok, vp / piv, mask=cm)
            tl.store(op, vk, mask=cm)
            rk = R + K * N + cols
            rp = R + brow * N + cols
            vk = tl.load(rk, mask=cm, other=0.0)
            vp = tl.load(rp, mask=cm, other=0.0)
            tl.store(rk, vp / piv, mask=cm)
            tl.store(rp, vk, mask=cm)


@triton.jit
def _tensorinv_elim_kernel(W, R, N, K, BM: tl.constexpr, BN: tl.constexpr):
    """Subtract factor * row K from every other row (row K is untouched)."""
    rows = tl.program_id(0) * BM + tl.arange(0, BM)
    rmask = rows < N
    f = tl.load(W + rows * N + K, mask=rmask, other=0.0)
    f = tl.where(rows != K, f, 0.0)
    for j0 in range(0, N, BN):
        cols = j0 + tl.arange(0, BN)
        cm = cols < N
        m = rmask[:, None] & cm[None, :]
        wrow = tl.load(W + K * N + cols, mask=cm, other=0.0)
        rrow = tl.load(R + K * N + cols, mask=cm, other=0.0)
        o = rows[:, None] * N + cols[None, :]
        tw = tl.load(W + o, mask=m, other=0.0)
        tr = tl.load(R + o, mask=m, other=0.0)
        tl.store(W + o, tw - f[:, None] * wrow[None, :], mask=m)
        tl.store(R + o, tr - f[:, None] * rrow[None, :], mask=m)


@triton.jit
def _tensorinv_copy_kernel(R, B, N, BLOCK: tl.constexpr):
    rows = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    cols = tl.program_id(1) * BLOCK + tl.arange(0, BLOCK)
    m = (rows[:, None] < N) & (cols[None, :] < N)
    o = rows[:, None] * N + cols[None, :]
    v = tl.load(R + o, mask=m, other=0.0)
    tl.store(B + o, v, mask=m)


@triton.jit
def _tensorinv_residual_kernel(A, X, R, N, BLOCK: tl.constexpr):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = offs < N * N
    rows = offs // N
    cols = offs % N
    high = tl.full((BLOCK,), 0.0, tl.float32)
    low = tl.full((BLOCK,), 0.0, tl.float32)
    for k in range(N):
        a = tl.load(A + rows * N + k, mask=mask, other=0.0).to(tl.float32)
        x = tl.load(X + k * N + cols, mask=mask, other=0.0)
        product = a * x
        product_error = tl.fma(a, x, -product)
        total = high + product
        recovered = total - high
        sum_error = (high - (total - recovered)) + (product - recovered)
        low = low + (sum_error + product_error)
        high = total
    residual = (tl.where(rows == cols, 1.0, 0.0) - high) - low
    tl.store(R + offs, residual, mask=mask)


@triton.jit
def _tensorinv_refine_kernel(X, R, Y, N, BLOCK: tl.constexpr):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = offs < N * N
    rows = offs // N
    cols = offs % N
    correction = tl.full((BLOCK,), 0.0, tl.float32)
    for k in range(N):
        x = tl.load(X + rows * N + k, mask=mask, other=0.0)
        r = tl.load(R + k * N + cols, mask=mask, other=0.0)
        correction = tl.fma(x, r, correction)
    original = tl.load(X + offs, mask=mask, other=0.0)
    tl.store(Y + offs, original + correction, mask=mask)


def _launch_inverse(a2d, dst, n):
    if n <= _TILE_MAX:
        block = max(4, triton.next_power_of_2(n))
        # One warp keeps 16-wide tiles fully intra-warp (shuffle only, no
        # shared-memory barrier phases).  A 32-wide tile is volume bound at one
        # warp (16 elements per lane), so it gets more lanes to spread the
        # per-step elementwise work; 64+ wide tiles keep the wide default.
        if block <= 16:
            num_warps = 1
        elif block <= 32:
            num_warps = 4
        else:
            num_warps = 8
        _tensorinv_tile_kernel[(1,)](
            a2d, dst, n, BLOCK=block, MASKED=(block != n), num_warps=num_warps
        )
    else:
        dev = dst.device
        ws = torch.empty((n, n), dtype=torch.float32, device=dev)
        rhs = torch.empty((n, n), dtype=torch.float32, device=dev)
        blk = 64
        grid = (triton.cdiv(n, blk), triton.cdiv(n, blk))
        _tensorinv_init_kernel[grid](a2d, ws, rhs, n, BLOCK=blk)
        for k in range(n):
            _tensorinv_pivot_kernel[(1,)](ws, rhs, n, k, BS=128, num_warps=1)
            _tensorinv_elim_kernel[(triton.cdiv(n, 32),)](
                ws, rhs, n, k, BM=32, BN=128, num_warps=4
            )
        _tensorinv_copy_kernel[grid](rhs, dst, n, BLOCK=blk)


def _launch(a2d, dst, n):
    inverse = torch.empty((n, n), dtype=torch.float32, device=dst.device)
    _launch_inverse(a2d, inverse, n)
    residual = torch.empty_like(inverse)
    working = torch.empty_like(inverse)
    block = 256
    grid = (triton.cdiv(n * n, block),)
    for step in range(2):
        # Preserve the explicit TwoSum/TwoProd rounding boundaries. Only the
        # product-error extraction uses an explicitly requested fused FMA.
        _tensorinv_residual_kernel[grid](
            a2d,
            inverse,
            residual,
            n,
            BLOCK=block,
            num_warps=4,
            enable_fp_fusion=False,
        )
        target = working if step == 0 else dst
        _tensorinv_refine_kernel[grid](
            inverse, residual, target, n, BLOCK=block, num_warps=4
        )
        if step == 0:
            inverse, working = working, inverse


def linalg_tensorinv(A, ind=2, *, out=None):
    if not isinstance(A, torch.Tensor):
        A = torch.as_tensor(A)
    ind = int(ind)
    _check_inv_input(A, ind)

    shape = A.shape
    n = 1
    for i in range(ind):
        n *= shape[i]
    out_shape = tuple(shape[ind:]) + tuple(shape[:ind])

    if out is None:
        res = torch.empty(out_shape, dtype=A.dtype, device=A.device)
        if n:
            src = A if A.is_contiguous() else A.contiguous()
            _launch(src.view(n, n), res.view(n, n), n)
        return res

    if out.is_contiguous() and tuple(out.shape) == out_shape and out.dtype == A.dtype:
        if n:
            src = A if A.is_contiguous() else A.contiguous()
            _launch(src.view(n, n), out.view(n, n), n)
        return out

    tmp = torch.empty(out_shape, dtype=A.dtype, device=A.device)
    if n:
        src = A if A.is_contiguous() else A.contiguous()
        _launch(src.view(n, n), tmp.view(n, n), n)
    out.copy_(tmp)
    return out
